class EngineModule25:
    """Implementation of EngineModule25 supporting process(data) and get_status()."""

    def __init__(self):
        self._status = "ready"
        self._last_processed = None

    def process(self, data):
        """Processes the input data and updates the internal status and state."""
        self._last_processed = data
        self._status = "success"
        return {"input": data, "status": "success"}

    def get_status(self):
        """Returns the current status of the engine module."""
        return self._status
